use arena_scores::Board;
use std::sync::Arc;
use std::thread;

#[test]
fn concurrent_awards_do_not_lose_points() {
    let board = Arc::new(Board::new());
    board.join(1, 0);
    const THREADS: usize = 8;
    const AWARDS: i64 = 5000;
    let mut handles = Vec::new();
    for _ in 0..THREADS {
        let board = Arc::clone(&board);
        handles.push(thread::spawn(move || {
            for _ in 0..AWARDS {
                board.award(1, 1);
            }
        }));
    }
    for h in handles {
        h.join().unwrap();
    }
    assert_eq!(board.score(1), (THREADS as i64) * AWARDS);
    assert_eq!(board.total(), (THREADS as i64) * AWARDS);
}

#[test]
fn opposite_transfers_do_not_deadlock() {
    let board = Arc::new(Board::new());
    board.join(1, 100);
    board.join(2, 100);
    let mut handles = Vec::new();
    for _ in 0..16 {
        for (a, b) in [(1u32, 2u32), (2u32, 1u32)] {
            let board = Arc::clone(&board);
            handles.push(thread::spawn(move || {
                for _ in 0..50_000 {
                    board.transfer(a, b, 1);
                }
            }));
        }
    }
    for h in handles {
        h.join().unwrap();
    }
    assert_eq!(board.score(1), 100);
    assert_eq!(board.score(2), 100);
    assert_eq!(board.total(), 200);
}

#[test]
fn transfer_to_self_is_a_noop() {
    let board = Board::new();
    board.join(1, 42);
    board.transfer(1, 1, 7);
    assert_eq!(board.score(1), 42);
    assert_eq!(board.total(), 42);
}
